using System;using System.Linq;using UnityEngine;using UnityEditor;public static class FixPlanter19 { public static object Main(){string folder="Assets/ShooterSurvival/Models/Chapters/Chapters45/Ch5Toon20261004";var paths=AssetDatabase.FindAssets("t:Mesh",new[]{folder}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>p.Contains("Batch-revision2-store-")&&p.Contains("2c03922b57cfd1945a17b2bffbe946fb")).ToArray();if(paths.Length!=8)throw new Exception("Expected eight isolated first-floor plant batches");foreach(var path in paths){var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(m.bounds.min.y<.8f)throw new Exception("Already lowered; inspect instead of duplicate");m.vertices=m.vertices.Select(v=>v-Vector3.up*.62f).ToArray();m.RecalculateBounds();EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);}return new{corrected=paths.Length,sourceModelEdited=false};}}
